SET search_path TO gapmap;

create table assessments (archived boolean not null, mini_quiz boolean not null, published boolean not null, class_room_id bigint not null, created_by_id bigint not null, id bigint not null generated by default as identity, topic_id bigint, version bigint not null, title varchar(255), primary key (id));
create table attempts (total_score double precision not null, assessment_id bigint not null, id bigint not null generated by default as identity, student_id bigint not null, submitted_at timestamp(6) with time zone not null, payload_hash varchar(64) not null, submission_key varchar(255) not null, primary key (id));
create table class_rooms (id bigint not null generated by default as identity, teacher_id bigint not null, join_code varchar(255) not null, name varchar(255), primary key (id));
create table enrollments (class_room_id bigint not null, student_id bigint not null, primary key (class_room_id, student_id));
create table learning_gaps (attempt_id bigint not null, id bigint not null generated by default as identity, student_id bigint not null, topic_id bigint not null, gap_type varchar(255), status varchar(255), primary key (id));
create table learning_materials (archived boolean not null, id bigint not null generated by default as identity, topic_id bigint not null, url_or_content varchar(12000), title varchar(255), type varchar(255), primary key (id));
create table question_options (correct boolean not null, id bigint not null generated by default as identity, question_id bigint not null, text varchar(2000), primary key (id));
create table questions (assessment_id bigint not null, id bigint not null generated by default as identity, topic_id bigint not null, explanation varchar(4000), text varchar(4000), difficulty varchar(255), primary key (id));
create table recommendations (order_index integer not null, gap_id bigint not null, id bigint not null generated by default as identity, material_id bigint not null, student_id bigint not null, explanation varchar(4000), status varchar(255), primary key (id));
create table responses (correct boolean not null, attempt_id bigint not null, id bigint not null generated by default as identity, question_id bigint not null, selected_option_id bigint not null, confidence_level varchar(255), primary key (id));
create table topic_prerequisites (prerequisite_id bigint not null, topic_id bigint not null, primary key (prerequisite_id, topic_id));
create table topic_results (score_percent double precision not null, attempt_id bigint not null, id bigint not null generated by default as identity, topic_id bigint not null, mastery_level varchar(255), primary key (id));
create table topics (id bigint not null generated by default as identity, teacher_id bigint not null, description varchar(4000), name varchar(255), primary key (id));
create table users (id bigint not null generated by default as identity, email varchar(255) not null, name varchar(255) not null, password_hash varchar(255) not null, role varchar(255) not null, token_version integer, primary key (id));
create table password_reset_tokens (id bigint not null generated by default as identity, user_id bigint not null, token_hash varchar(64) not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, used_at timestamp(6) with time zone, primary key (id));
